class Solution {
    bool check(const string& s,const string& p,vector<int>& removable,int count){
        vector<bool> removed(s.size());
        for(int i=0;i<count;++i)removed[removable[i]]=true;
        int matched=0;
        for(int i=0;i<(int)s.size()&&matched<(int)p.size();++i)if(!removed[i]&&s[i]==p[matched])++matched;
        return matched==(int)p.size();
    }
    public: int maximumRemovals(string s,string p,vector<int>& removable){
        int left=0,right=removable.size();
        while(left<right){
            int middle=left+(right-left+1)/2;
            if(check(s,p,removable,middle))left=middle;
            else right=middle-1;
        }
        return left;
    }
};
